import json
import os.path as opath

import codegen
from codegen import compatibility, datatypes, figure, utils, validators


def test_package_reexports_public_codegen_helpers():
    assert codegen.build_datatype_py is datatypes.build_datatype_py
    assert codegen.write_datatype_py is datatypes.write_datatype_py
    assert codegen.write_figure_classes is figure.write_figure_classes
    assert codegen.TraceNode is utils.TraceNode
    assert codegen.PlotlyNode is utils.PlotlyNode
    assert codegen.get_validator_params is validators.get_validator_params
    assert codegen.DEPRECATED_DATATYPES is compatibility.DEPRECATED_DATATYPES


def test_preprocess_schema_adds_template_and_renames_sankey_colorscales():
    original_layout = {"existing": {"valType": "number"}}
    concentrationscales = {"description": "Concentration scale."}
    schema = {
        "layout": {"layoutAttributes": original_layout},
        "traces": {
            "scatter": {},
            "bar": {},
            "sankey": {
                "attributes": {
                    "link": {
                        "colorscales": {
                            "items": {"concentrationscales": concentrationscales}
                        }
                    }
                }
            },
        },
    }

    result = codegen.preprocess_schema(schema)

    assert result is None
    layout = schema["layout"]["layoutAttributes"]
    assert layout["existing"] is original_layout["existing"]
    assert layout["template"]["data"]["scatters"] == {
        "items": {"scatter": {}},
        "role": "object",
    }
    assert layout["template"]["data"]["bars"] == {
        "items": {"bar": {}},
        "role": "object",
    }
    assert layout["template"]["layout"] == {}
    assert "Default attributes to be applied to the plot." in (
        layout["template"]["description"]
    )
    items = schema["traces"]["sankey"]["attributes"]["link"]["colorscales"]["items"]
    assert "concentrationscales" not in items
    assert items["colorscale"] is concentrationscales


def test_preprocess_schema_does_not_create_legacy_sankey_key_if_absent():
    schema = {
        "layout": {"layoutAttributes": {}},
        "traces": {
            "scatter": {},
            "sankey": {
                "attributes": {
                    "link": {"colorscales": {"items": {"colorscale": {"x": 1}}}}
                }
            },
        },
    }

    codegen.preprocess_schema(schema)

    items = schema["traces"]["sankey"]["attributes"]["link"]["colorscales"]["items"]
    assert items == {"colorscale": {"x": 1}}


