class FakeNode:
    def __init__(
        self,
        path_parts,
        name_undercase,
        name_datatype_class,
        *,
        is_compound=True,
        child_compound_datatypes=(),
    ):
        self.path_parts = path_parts
        self.parent_path_parts = path_parts[:-1]
        self.name_undercase = name_undercase
        self.name_datatype_class = name_datatype_class
        self.is_compound = is_compound
        self.child_compound_datatypes = list(child_compound_datatypes)

    @property
    def path_str(self):
        return ".".join(self.path_parts)


def test_perform_codegen_orchestrates_generation_and_cleans_stale_directories(
    monkeypatch, tmp_path
):
    project_root = tmp_path / "project"
    outdir = project_root / "output"
    schema_dir = project_root / "codegen" / "resources"
    schema_dir.mkdir(parents=True)
    schema_path = schema_dir / "plot-schema.json"
    schema_path.write_text(json.dumps({"fake": "schema"}))
    stale_validators = outdir / "validators"
    stale_graph_objs = outdir / "graph_objs"
    stale_validators.mkdir(parents=True)
    stale_graph_objs.mkdir()
    (stale_validators / "old.json").write_text("{}")
    (stale_graph_objs / "old.py").write_text("old = True")

    traces_root = FakeNode((), "data", "Data")
    marker = FakeNode(("scatter",), "marker", "Marker")
    scatter = FakeNode(
        (), "scatter", "Scatter", child_compound_datatypes=[marker]
    )
    layout = FakeNode(("layout",), "layout", "Layout")
    frame = FakeNode(("frame",), "frame", "Frame")
    layout_validator = object()
    frame_validator = object()
    data_validator = object()
    calls = []

    class FakePlotlyNode:
        @staticmethod
        def get_all_datatype_nodes(plotly_schema, node_class):
            calls.append(("all_datatype", plotly_schema, node_class))
            return [scatter, layout, frame]

        @staticmethod
        def get_all_compound_datatype_nodes(plotly_schema, node_class):
            calls.append(("all_compound", plotly_schema, node_class))
            if node_class is codegen.LayoutNode:
                return [layout]
            if node_class is codegen.FrameNode:
                return [frame]
            raise AssertionError("Unexpected node class")

    class LayoutNodeMarker:
        pass

    class FrameNodeMarker:
        pass

    layout.get_validator_instance = lambda: layout_validator
    frame.get_validator_instance = lambda: frame_validator

    def fake_preprocess(schema):
        calls.append(("preprocess", schema))

    def fake_get_validator_params(node, store):
        store[node.name_undercase] = {"params": {}, "superclass": "Fake"}

    def fake_get_data_validator_params(node, store):
        store["data"] = {"params": {}, "superclass": "BaseDataValidator"}

    def fake_write_validator_json(out, params):
        calls.append(("write_validators", out, dict(params)))

    def fake_write_datatype_py(out, node):
        calls.append(("write_datatype", out, node))

    def fake_write_deprecated_datatypes(out):
        calls.append(("write_deprecated", out))

    def fake_get_data_validator_instance(node):
        calls.append(("data_validator_instance", node))
        return data_validator

    def fake_write_figure_classes(*args):
        calls.append(("write_figures",) + args)

    def fake_write_graph_objs_graph_objs(out):
        calls.append(("write_graph_objs_alias", out))

    def fake_write_init_py(pkg_root, path_parts, rel_modules, rel_classes, init_extra):
        calls.append(
            ("write_init", pkg_root, path_parts, rel_modules, rel_classes, init_extra)
        )

    def fake_build_from_imports_py(rel_modules, rel_classes, init_extra=""):
        calls.append(("build_imports", rel_modules, rel_classes, init_extra))
        return "GENERATED IMPORTS"

    def fake_reformat_code(out):
        calls.append(("reformat", out))

    monkeypatch.setattr(codegen, "preprocess_schema", fake_preprocess)
    monkeypatch.setattr(codegen, "TraceNode", lambda schema: traces_root)
    monkeypatch.setattr(codegen, "LayoutNode", LayoutNodeMarker)
    monkeypatch.setattr(codegen, "FrameNode", FrameNodeMarker)
    monkeypatch.setattr(codegen, "PlotlyNode", FakePlotlyNode)
    monkeypatch.setattr(codegen, "get_validator_params", fake_get_validator_params)
    monkeypatch.setattr(
        codegen, "get_data_validator_params", fake_get_data_validator_params
    )
    monkeypatch.setattr(codegen, "write_validator_json", fake_write_validator_json)
    monkeypatch.setattr(codegen, "write_datatype_py", fake_write_datatype_py)
    monkeypatch.setattr(
        codegen, "write_deprecated_datatypes", fake_write_deprecated_datatypes
    )
    monkeypatch.setattr(
        codegen, "get_data_validator_instance", fake_get_data_validator_instance
    )
    monkeypatch.setattr(codegen, "write_figure_classes", fake_write_figure_classes)
    monkeypatch.setattr(
        codegen, "write_graph_objs_graph_objs", fake_write_graph_objs_graph_objs
    )
    monkeypatch.setattr(codegen, "write_init_py", fake_write_init_py)
    monkeypatch.setattr(
        codegen, "build_from_imports_py", fake_build_from_imports_py
    )
    monkeypatch.setattr(codegen, "reformat_code", fake_reformat_code)

    codegen.perform_codegen(str(outdir), noformat=False)

    assert not (stale_validators / "old.json").exists()
    assert not stale_graph_objs.exists()
    assert (outdir / "validators").is_dir()
    assert (outdir / "graph_objects" / "__init__.py").read_text() == (
        "# ruff: noqa: F401\nGENERATED IMPORTS"
    )

    assert ("preprocess", {"fake": "schema"}) in calls
    assert ("all_datatype", {"fake": "schema"}, LayoutNodeMarker) in calls
    assert ("all_datatype", {"fake": "schema"}, FrameNodeMarker) in calls
    assert (
        "write_validators",
        str(outdir),
        {
            "layout": {"params": {}, "superclass": "Fake"},
            "scatter": {"params": {}, "superclass": "Fake"},
            "frame": {"params": {}, "superclass": "Fake"},
            "data": {"params": {}, "superclass": "BaseDataValidator"},
        },
    ) in calls
    assert calls.count(("data_validator_instance", traces_root)) == 1
    assert (
        "write_figures",
        str(outdir),
        traces_root,
        data_validator,
        layout_validator,
        frame_validator,
        [],
        [],
    ) in calls
    assert ("write_deprecated", str(outdir)) in calls
    assert ("write_graph_objs_alias", str(outdir)) in calls
