import json

import pytest

from codegen.utils import TraceNode
from codegen.validators import (
    build_data_validator_params,
    get_data_validator_instance,
    get_data_validator_params,
    get_validator_params,
    write_validator_json,
)


def test_get_validator_params_stores_evaluable_params_and_superclass(plotly_schema):
    name_node = TraceNode(plotly_schema, ("scatter", "name"))
    store = {}

    get_validator_params(name_node, store)

    assert store == {
        "scatter.name": {
            "params": {
                "plotly_name": "name",
                "parent_name": "scatter",
            },
            "superclass": "StringValidator",
        }
    }


def test_get_validator_params_includes_custom_color_scale_path(plotly_schema):
    scatter = TraceNode(plotly_schema, ("scatter",))
    marker = next(n for n in scatter.children if n.plotly_name == "marker")
    color = next(n for n in marker.children if n.plotly_name == "color")
    store = {}

    get_validator_params(color, store)

    entry = store["scatter.marker.color"]
    assert entry["superclass"] == "ColorValidator"
    assert entry["params"]["plotly_name"] == "color"
    assert entry["params"]["parent_name"] == "scatter.marker"
    assert entry["params"]["colorscale_path"] == "scatter.marker.colorscale"


def test_get_validator_params_validates_store_and_node(plotly_schema):
    node = TraceNode(plotly_schema, ("scatter", "name"))

    with pytest.raises(AssertionError):
        get_validator_params(node, [])

    with pytest.raises(AssertionError):
        get_validator_params(TraceNode(plotly_schema, ("scatter", "type")), {})


def test_build_data_validator_params_maps_trace_types_to_classes(plotly_schema):
    params = build_data_validator_params(TraceNode(plotly_schema))

    assert params == {
        "class_strs_map": {
            "bar": "Bar",
            "barpolar": "Barpolar",
            "scatter": "Scatter",
        },
        "plotly_name": "data",
        "parent_name": "",
    }


def test_get_data_validator_params_stores_data_entry(plotly_schema):
    store = {"existing": {"params": {}, "superclass": "Example"}}

    get_data_validator_params(TraceNode(plotly_schema), store)

    assert store["existing"]["superclass"] == "Example"
    assert store["data"] == {
        "params": {
            "class_strs_map": {
                "bar": "Bar",
                "barpolar": "Barpolar",
                "scatter": "Scatter",
            },
            "plotly_name": "data",
            "parent_name": "",
        },
        "superclass": "BaseDataValidator",
    }

    with pytest.raises(AssertionError):
        get_data_validator_params(TraceNode(plotly_schema), [])


def test_get_data_validator_instance_coerces_valid_trace_dicts(plotly_schema):
    validator = get_data_validator_instance(TraceNode(plotly_schema))

    result = validator.validate_coerce(
        [
            {"type": "scatter", "name": "points"},
            {"type": "bar", "name": "bars"},
        ]
    )

    assert [type(trace).__name__ for trace in result] == ["Scatter", "Bar"]
    assert [trace.name for trace in result] == ["points", "bars"]


def test_get_data_validator_instance_rejects_unknown_trace_type(plotly_schema):
    validator = get_data_validator_instance(TraceNode(plotly_schema))

    with pytest.raises(ValueError, match="Invalid element.*bogus"):
        validator.validate_coerce([{"type": "bogus", "name": "nope"}])


def test_write_validator_json_writes_indented_json_to_validators_dir(tmp_path):
    validators_dir = tmp_path / "validators"
    validators_dir.mkdir()
    params = {
        "scatter.name": {
            "params": {"plotly_name": "name", "parent_name": "scatter"},
            "superclass": "StringValidator",
        },
        "data": {"params": {}, "superclass": "BaseDataValidator"},
    }

    write_validator_json(str(tmp_path), params)

    filepath = validators_dir / "_validators.json"
    assert filepath.is_file()
    assert json.loads(filepath.read_text()) == params
    assert '\n    "scatter.name": {' in filepath.read_text()


def test_write_validator_json_rejects_non_dictionary_before_writing(tmp_path):
    with pytest.raises(ValueError, match="Expected params to be a dictionary"):
        write_validator_json(str(tmp_path), [("key", "value")])

    assert not (tmp_path / "validators").exists()


def test_write_validator_json_requires_existing_output_directory(tmp_path):
    with pytest.raises(FileNotFoundError):
        write_validator_json(str(tmp_path), {})

